import{_ as t,o as a,c as o,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const m=JSON.parse('{"title":"Mobile Media Package Review, Campaign Tracking & Client Content Request Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/08-mobile-application/mobile-package-campaign/spec.md","filePath":"feature/modules/08-mobile-application/mobile-package-campaign/spec.md"}'),i={name:"feature/modules/08-mobile-application/mobile-package-campaign/spec.md"};function r(c,e,s,l,d,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="mobile-media-package-review-campaign-tracking-client-content-request-workflows" tabindex="-1">Mobile Media Package Review, Campaign Tracking &amp; Client Content Request Workflows <a class="header-anchor" href="#mobile-media-package-review-campaign-tracking-client-content-request-workflows" aria-label="Permalink to &quot;Mobile Media Package Review, Campaign Tracking &amp; Client Content Request Workflows&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>mobile-package-campaign</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>08-mobile-application</code> — BrandHub Mobile Application (Expo SDK 58 / React Native 0.88)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>mobile-package-campaign</code>, <code>mobile-nav-role-parity (Content Requests &amp; Campaign Partners)</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/04-media-package-campaign/README.html">3.5 Media Package &amp; Media Campaign</a> (<code>3.5.1–3.5.13</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Enable <code>Owner</code>, <code>Manager</code>, and <code>Client</code> users on the go to inspect and approve <strong>Workspace Media Packages</strong> (<code>MediaPackageScreen.tsx</code>), monitor <strong>Media Campaigns &amp; Collaborator Partners</strong> (<code>CampaignsScreen.tsx</code>, <code>CampaignDetailScreen.tsx</code>, <code>CampaignPartnersSection.tsx</code>), and execute the full <strong>Client Content Request lifecycle</strong> (<code>ContentRequestsScreen.tsx</code>, <code>ContentRequestDetailScreen.tsx</code>, <code>ContentRequestFormScreen.tsx</code>) with optimistic version concurrency (<code>expectedVersion</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As a <code>Client</code> away from my desk, I want to review and approve proposed Media Packages and Campaigns, submit supplemental Content Requests with attachments/deadlines, and track request acceptance on my phone.</li><li>As a <code>Manager</code> or <code>Owner</code>, I want to receive, accept (spawning a Campaign Task), or deny Client Content Requests with clear reason notes directly from mobile.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Media Package Inspection, Negotiation &amp; Approval (<code>MediaPackageScreen.tsx</code>):</strong> Displays deliverable line items, pricing/cycle model, negotiation history (<code>GET /media-package/history</code>), counter-proposal notes (<code>PATCH /media-package/negotiate</code>), and 1-tap <code>Client</code>/<code>Manager</code> approval (<code>POST /media-package/approve</code>).</li><li><strong>Campaign Overview, Brief &amp; Partner Tracking (<code>CampaignsScreen.tsx</code>, <code>CampaignDetailScreen.tsx</code>):</strong> Renders Campaign master brief, milestone progress, deliverable task breakdown, Campaign approval (<code>POST /campaigns/{id}/approve</code>), and linked third-party Collaborator statuses (<code>CampaignPartnersSection.tsx</code>).</li><li><strong>Full Content Request CRUD &amp; Review (<code>ContentRequestsScreen.tsx</code>, <code>ContentRequestDetailScreen.tsx</code>, <code>ContentRequestFormScreen.tsx</code>):</strong> Driven by backend <code>can*</code> capability flags and <code>expectedVersion</code> optimistic concurrency (<code>contentRequest.ts</code>), formatting deadlines in Workspace timezone (<code>DD/MM/YYYY HH:mm</code>) and enforcing <code>Creator</code> exclusion per <code>ContentRequestAccess</code>.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>mediaPackage.*</code>, <code>campaign.*</code>, <code>contentRequests.*</code> in <code>src/i18n/locales/en.json</code> &amp; <code>src/i18n/locales/vi/common.json</code> (<code>tr()</code>)) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> Parity with <code>pages/campaign/*</code>, <code>pages/client/components/{ServicePackageModal,ClientContentRequests}.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/{MediaPackageScreen,CampaignsScreen,CampaignDetailScreen,ContentRequestsScreen,ContentRequestDetailScreen,ContentRequestFormScreen}.tsx</code>, <code>src/components/campaign/CampaignPartnersSection.tsx</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;">`GET/POST/PATCH /api/v1/workspaces/{workspaceId}/media-package[/negotiate</td><td style="text-align:left;">/approve</td><td style="text-align:left;">/history]`</td></tr><tr><td style="text-align:left;"><code>GET/POST /api/v1/workspaces/{workspaceId}/campaigns/** &amp; /campaign-collaborators</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Client</code>)</td><td style="text-align:left;"><code>WorkspaceCampaignController</code> &amp; <code>CampaignCollaboratorController</code> &lt;- <code>campaignService.ts</code></td></tr><tr><td style="text-align:left;">`GET/POST/PATCH/DELETE /api/v1/workspaces/{workspaceId}/content-requests/** &amp; /{id}/{receive</td><td style="text-align:left;">accept</td><td style="text-align:left;">deny}`</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Stale Content Request Edit (<code>409 CONFLICT</code>):</strong> Mobile form prompts user to reload latest version when <code>Manager</code> receives/locks a request while <code>Client</code> is editing.</li><li><strong>Deadline Validation:</strong> Rejects past deadlines in Workspace IANA timezone before submission.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/04-media-package-campaign/README.html">3.5 Media Package &amp; Media Campaign</a> (<code>3.5.1–3.5.13</code>)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/04-media-package-campaign.html">BA 04 Media Package &amp; Campaign</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const u=t(i,[["render",r]]);export{m as __pageData,u as default};
